-- `priority_bodyweight` pour TOUT le catalogue sans matériel, pas seulement les
-- nouvelles lignes : le rang dense de `priority` par (muscle × geste × rôle),
-- plafonné à 3, pour que les trois meilleures options d'une forme de slot
-- concourent réellement. Même calcul que le snapshot embarqué ; rejouable.
WITH classe AS (
  SELECT id, dense_rank() OVER (
           PARTITION BY muscle_primary, movement_group, compound ORDER BY priority
         ) AS rang
    FROM public.movement_catalog
   WHERE discipline_muscu AND load_mode = 'bodyweight' AND weight_bodyweight > 0
)
UPDATE public.movement_catalog AS m
   SET priority_bodyweight = LEAST(c.rang, 3)
  FROM classe AS c
 WHERE c.id = m.id;
